import{_ as n,o as t,c as i,a3 as r}from"./chunks/framework.B5WAEDB7.js";const b=JSON.parse('{"title":"Ansicht teilen","description":"Eine Ansicht als privaten Link teilen, per QR-Code oder eingebettet.","frontmatter":{"title":"Ansicht teilen","description":"Eine Ansicht als privaten Link teilen, per QR-Code oder eingebettet."},"headers":[],"relativePath":"ansichten/ansicht-teilen.md","filePath":"ansichten/ansicht-teilen.md","lastUpdated":1786455650000}'),a={name:"ansichten/ansicht-teilen.md"};function s(l,e,o,d,h,c){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="ansicht-teilen" tabindex="-1">Ansicht teilen <a class="header-anchor" href="#ansicht-teilen" aria-label="Permalink to &quot;Ansicht teilen&quot;">​</a></h1><p>Jede Ansicht lässt sich über einen Link teilen — mit Personen, die kein ApptiveGrid-Konto haben.</p><h2 id="link-erstellen" tabindex="-1">Link erstellen <a class="header-anchor" href="#link-erstellen" aria-label="Permalink to &quot;Link erstellen&quot;">​</a></h2><p>Klicken Sie auf <strong>Teilen</strong>. Solange kein Link besteht, steht dort:</p><blockquote><p><strong>Erstellen Sie einen freigebbaren Link zur Ansicht</strong><em>Sie können den Link an eine beliebige Person senden oder in eine Website einbetten.</em></p></blockquote><p>Nach dem Erstellen:</p><blockquote><p><strong>Diese Ansicht wird über einen privaten Link freigegeben</strong><em>Über diesen Link sind Daten dieser Ansicht sichtbar.</em></p></blockquote><div class="danger custom-block"><p class="custom-block-title">Standardmäßig öffentlich</p><p>Ohne zusätzliche Beschränkung kann <strong>jede Person mit dem Link</strong> die Ansicht öffnen. Der Link ist nicht erratbar, aber ungeschützt — wird er weitergeleitet, funktioniert er dort weiter.</p><p>Entscheiden Sie <strong>vor</strong> dem Verteilen über die Zugriffsbeschränkung. → <a href="/zusammenarbeit/zugriff-beschraenken">Zugriff auf geteilte Inhalte</a></p></div><h2 id="was-empfanger-sehen" tabindex="-1">Was Empfänger sehen <a class="header-anchor" href="#was-empfanger-sehen" aria-label="Permalink to &quot;Was Empfänger sehen&quot;">​</a></h2><p><strong>Genau das, was in dieser Ansicht sichtbar ist</strong> — mit Filter, Sortierung, Gruppierung und den eingeblendeten Spalten.</p><div class="warning custom-block"><p class="custom-block-title">Filter sind Sichtschutz, kein Zugriffsschutz</p><p>Ausgeblendete Spalten und Filter verringern, was ankommt. Verlassen Sie sich bei vertraulichen Daten aber nicht allein darauf: Kombinieren Sie sie mit einer Zugriffsbeschränkung, oder legen Sie sensible Daten gar nicht erst in dasselbe Grid.</p></div><div class="tip custom-block"><p class="custom-block-title">Eine eigene Ansicht fürs Teilen</p><p>Teilen Sie nicht Ihre Arbeitsansicht. Legen Sie eine Kopie an (<em>Ansicht duplizieren</em>), blenden Sie alles Interne aus, filtern Sie auf das Nötige — und teilen Sie diese. So ändert sich das Geteilte nicht versehentlich mit, wenn Sie Ihre Arbeitsansicht anpassen.</p></div><h2 id="neue-eintrage-uber-die-ansicht-zulassen" tabindex="-1">Neue Einträge über die Ansicht zulassen <a class="header-anchor" href="#neue-eintrage-uber-die-ansicht-zulassen" aria-label="Permalink to &quot;Neue Einträge über die Ansicht zulassen&quot;">​</a></h2><p>Der Dialog bietet an:</p><blockquote><p><em>Bitte wählen Sie optional ein Formular aus, um die Erstellung neuer Einträge zu ermöglichen.</em></p></blockquote><p>Wählen Sie ein <a href="/formulare/formular-erstellen">Formular</a>, können Empfänger neue Einträge anlegen. Ohne Formular lässt sich über den Link kein neuer Eintrag anlegen.</p><div class="tip custom-block"><p class="custom-block-title">Bestehende Einträge bearbeiten hängt von der Rolle ab</p><p>Ob eine Person bestehende Einträge in der geteilten Ansicht bearbeiten kann, entscheidet nicht das Formular, sondern ihre eigene Berechtigung: Ist sie beim Öffnen des Links bei ApptiveGrid angemeldet und hat eine Rolle mit Bearbeitungsrecht auf das Grid, kann sie direkt in der Ansicht bearbeiten. Ohne Anmeldung oder ohne passende Rolle bleibt es beim Lesen.</p></div><h2 id="qr-code-und-mobile-app" tabindex="-1">QR-Code und mobile App <a class="header-anchor" href="#qr-code-und-mobile-app" aria-label="Permalink to &quot;QR-Code und mobile App&quot;">​</a></h2><p>Der Teilen-Dialog hat mehrere Reiter:</p><table tabindex="0"><thead><tr><th>Reiter</th><th>Inhalt</th></tr></thead><tbody><tr><td><strong>Link</strong></td><td>Adresse zum <strong>Kopieren</strong>, <strong>Link öffnen</strong>, <strong>Entfernen</strong></td></tr><tr><td><strong>QR Code</strong></td><td>Code zum Scannen</td></tr><tr><td><strong>In App öffnen</strong></td><td>Ansicht zur mobilen App hinzufügen</td></tr></tbody></table><p>Der Untertitel lautet <em>Teile deine Ansicht mit Anderen und arbeite von überall.</em></p><h2 id="zugriff-beschranken" tabindex="-1">Zugriff beschränken <a class="header-anchor" href="#zugriff-beschranken" aria-label="Permalink to &quot;Zugriff beschränken&quot;">​</a></h2><p>Für Ansichten gilt das Modell mit <strong>Benutzername und Passwort</strong>:</p><table tabindex="0"><thead><tr><th>Option</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>Alle</strong></td><td><em>Jede Person mit dem Link kann zugreifen</em></td></tr><tr><td><strong>Mit Anmeldeinformationen</strong></td><td><em>Zugriff nur mit Benutzername und Passwort</em></td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Zugangsdaten nur einmal sichtbar</p><blockquote><p><em>Aus Sicherheitsgründen ist es nicht möglich, den Benutzernamen und das Passwort später einzusehen. Sie können diese jedoch jederzeit neu setzen.</em></p></blockquote><p>Notieren Sie beides sofort.</p></div><p>Für <strong>Formulare</strong> gilt ein anderes Modell — der Vergleich steht unter <a href="/zusammenarbeit/zugriff-beschraenken">Zugriff auf geteilte Inhalte</a>.</p><h2 id="einen-einzelnen-eintrag-teilen" tabindex="-1">Einen einzelnen Eintrag teilen <a class="header-anchor" href="#einen-einzelnen-eintrag-teilen" aria-label="Permalink to &quot;Einen einzelnen Eintrag teilen&quot;">​</a></h2><p>Statt der ganzen Ansicht lässt sich auch ein <strong>einzelner Eintrag</strong> teilen: über das Zeilenmenü <strong>Eintrag teilen</strong>. Dafür brauchen Sie ein Formular auf diesem Grid.</p><p>→ <a href="/formulare/eintraege-bearbeiten">Einträge per Formular bearbeiten</a></p><h2 id="ansicht-in-eine-seite-einbetten" tabindex="-1">Ansicht in eine Seite einbetten <a class="header-anchor" href="#ansicht-in-eine-seite-einbetten" aria-label="Permalink to &quot;Ansicht in eine Seite einbetten&quot;">​</a></h2><p>Innerhalb von ApptiveGrid binden Sie eine Ansicht über den Block <strong>Grid Ansicht</strong> in eine <a href="/seiten/was-sind-seiten">Seite</a> ein. Dort steuern Sie zusätzlich, ob Besucher suchen, filtern, exportieren und Einträge öffnen dürfen.</p><p>Für ein Portal ist das meist der bessere Weg als ein blanker Ansichtslink: Sie können Text, Erklärungen und mehrere Ansichten kombinieren.</p><p>→ <a href="/seiten/auswertungen">Ansichten und Auswertungen einbetten</a></p><h2 id="link-entfernen" tabindex="-1">Link entfernen <a class="header-anchor" href="#link-entfernen" aria-label="Permalink to &quot;Link entfernen&quot;">​</a></h2><p>Über <strong>Entfernen</strong> im Teilen-Dialog oder in der <a href="/zusammenarbeit/externe-links">Links-Übersicht</a> des Space.</p><p>Ein entfernter Link funktioniert sofort nicht mehr — auch nicht für Personen, die ihn gespeichert haben.</p><div class="warning custom-block"><p class="custom-block-title">Ansicht löschen macht Links ungültig</p><p>Löschen Sie die Ansicht selbst, werden alle darauf zeigenden Links und die daraus erzeugten Formulare unbrauchbar. ApptiveGrid warnt beim Löschen entsprechend.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/zusammenarbeit/zugriff-beschraenken">Zugriff auf geteilte Inhalte</a></li><li><a href="/zusammenarbeit/externe-links">Externe Links im Überblick</a></li><li><a href="/ansichten/spalten-verwalten">Spalten verwalten</a></li></ul>',39)])])}const g=n(a,[["render",s]]);export{b as __pageData,g as default};
